SELECT

FROM sys_question


    AND content LIKE CONCAT('%', #{query.keyword}, '%')


    AND question_type = #{query.questionType}


    AND is_fixed = #{query.isFixed}


    AND status = #{query.status}


ORDER BY sort ASC, id DESC

mapper.update:
